-- Peelr August 2026 questions: FRIENDS
-- Theme: End of Summer, before it's over. The last trip, the group chat, one more night out before everyone scatters.
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
-- Layer 1: playful, light, group energy
('friends', 1, 'What is the best night this group had all summer?', '¿Cuál fue la mejor noche que tuvo este grupo en todo el verano?'),
('friends', 1, 'If we planned one last trip before the season ends, who is organizing it and who is showing up late?', 'Si planeáramos un último viaje antes de que acabe la temporada, ¿quién lo organiza y quién llega tarde?'),
('friends', 1, 'What is the most unhinged thing that happened in the group chat this summer?', '¿Qué fue lo más descabellado que pasó en el chat del grupo este verano?'),
('friends', 1, 'Who here had the best summer, and who is going to argue about it?', '¿Quién aquí tuvo el mejor verano, y quién va a discutirlo?'),
('friends', 1, 'If our summer got one group photo on a billboard, which one are we using?', 'Si nuestro verano tuviera una foto de grupo en un cartel gigante, ¿cuál usaríamos?'),
('friends', 1, 'What is a summer plan we talked about constantly and never actually did?', '¿Qué plan de verano mencionamos mil veces y nunca hicimos?'),
('friends', 1, 'Who in this group is most likely to disappear once everyone gets busy again?', '¿Quién de este grupo va a desaparecer apenas todos se ocupen otra vez?'),
('friends', 1, 'What is the funniest thing that happened to you this summer?', '¿Qué fue lo más gracioso que te pasó este verano?'),
('friends', 1, 'If we had one more night out, where are we going and who is driving?', 'Si tuviéramos una salida más, ¿a dónde vamos y quién maneja?'),
('friends', 1, 'What song is always going to sound like this summer to all of us?', '¿Qué canción va a sonar siempre como este verano para todos nosotros?'),
('friends', 1, 'Who made the most questionable decision this summer, and are we allowed to bring it up?', '¿Quién tomó la decisión más cuestionable este verano, y podemos mencionarla?'),
('friends', 1, 'What is something you did this summer that you would never post?', '¿Qué hiciste este verano que nunca publicarías?'),
('friends', 1, 'If this summer had an award show for this group, what award is each of us winning?', 'Si este verano tuviera una premiación para este grupo, ¿qué premio gana cada uno?'),
('friends', 1, 'What is the pettiest thing you were annoyed about this summer?', '¿Cuál fue la tontería más pequeña que te molestó este verano?'),
('friends', 1, 'Who in this group gives the worst summer advice?', '¿Quién de este grupo da los peores consejos de verano?'),
('friends', 1, 'What is the best thing you ate this summer and where was it?', '¿Qué es lo mejor que comiste este verano y dónde fue?'),
('friends', 1, 'If we could redo one day from this summer, which day are we picking?', 'Si pudiéramos repetir un día de este verano, ¿cuál elegimos?'),
('friends', 1, 'What is a running joke from this summer that needs to survive into fall?', '¿Qué chiste interno de este verano tiene que sobrevivir hasta el otoño?'),
('friends', 1, 'Who took the most photos this summer and who is never in any of them?', '¿Quién tomó más fotos este verano y quién no sale en ninguna?'),
('friends', 1, 'What is one thing you want us all to do together before summer is over?', '¿Qué es lo único que quieres que hagamos todos juntos antes de que acabe el verano?'),
